import{_ as p,a0 as i,w as r,s as u,I as n,x as e,a1 as l,A as o,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端 | LCTT x X-CMD","titleTemplate":false,"description":"Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端 | LCTT (202312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端 | LCTT (202312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202312/20231212 Celeste- A Multi-Cloud Open-Source GUI File Sync Client in Rust","title":"Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端","tag":"202312","desc":""},"relativePath":"202312/20231212 Celeste- A Multi-Cloud Open-Source GUI File Sync Client in Rust.md","filePath":"[post].md"}'),m={name:"202312/20231212 Celeste- A Multi-Cloud Open-Source GUI File Sync Client in Rust.md"};function d(f,t,C,g,x,b){const s=i("Link");return r(),u("div",null,[t[22]||(t[22]=n("h1",{id:"celeste-rust-開發的多雲端開源-gui-文件同步客户端",tabindex:"-1"},[e("Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端 "),n("a",{class:"header-anchor",href:"#celeste-rust-開發的多雲端開源-gui-文件同步客户端","aria-label":"Permalink to “Celeste：Rust 開發的多雲端開源 GUI 文件同步客户端”"},"​")],-1)),t[23]||(t[23]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202312/20/210937s96kbwwycd71ciiu.jpg",alt:""})],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,"一個簡單而優雅的 GUI 同步客户端，提供雙向同步。")],-1)),n("p",null,[t[3]||(t[3]=e("當談到與雲文件同步時，我們有 ",-1)),l(s,{href:"https://itsfoss.com/insync-linux-review/"},{default:o(()=>[...t[0]||(t[0]=[e("Insync",-1)])]),_:1}),t[4]||(t[4]=e("、",-1)),l(s,{href:"https://itsfoss.com/freefilesync/"},{default:o(()=>[...t[1]||(t[1]=[e("FreeFileSync",-1)])]),_:1}),t[5]||(t[5]=e(" 等選項，以及 ",-1)),l(s,{href:"https://itsfoss.com/use-onedrive-linux-rclone/"},{default:o(()=>[...t[2]||(t[2]=[e("rclone",-1)])]),_:1}),t[6]||(t[6]=e(" 等幾個命令列工具。",-1))]),t[25]||(t[25]=a('<p>無論哪種情況，你也可以使用雲存儲提供商的同步客户端（如果他們有適用於 Linux 或任何其他平台的同步客户端）。但是，這並不是與多個雲存儲服務同步內容的最佳方式。</p><p>Insync 是一款付費工具，而 FreeFileSync 或 rclone 對於 Linux 新用户來説可能是一種難以接受的選擇。。</p><p>Celeste，一個簡單的 GUI 同步客户端，支持多個雲提供商。</p><blockquote><p>📋 該應用正在積極開發中。目前它可能沒有足夠的功能和貢獻者。歡迎你探索並幫助該項目。</p></blockquote><h3 id="適用於-linux-的基於-rust-的同步客户端" tabindex="-1">適用於 Linux 的基於 Rust 的同步客户端 <a class="header-anchor" href="#適用於-linux-的基於-rust-的同步客户端" aria-label="Permalink to “適用於 Linux 的基於 Rust 的同步客户端”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste.png" alt=""></p><p>Celeste 是一款用 Rust 編寫的應用，可確保你獲得快速的體驗。它在底層利用 rclone 來可靠地將數據與雲同步。</p><p>與某些現有選項不同，它沒有為你提供很多選擇。雖然一些用户可能會發現它有所欠缺，但其他用户可能會發現它是他們一直想要的簡單工具。</p><p>Celeste 僅支持雙向同步，目前沒有其他同步方式。</p><p>如果你想要單向同步（雲到本地，或本地到雲），那麼這不適合你。</p><p>該工具的工作機制很簡單。你只需從列表中添加雲提供商，或添加任何 WebDAV 服務器。</p><p>默認選項包括：<strong>Google Drive、Dropbox、Proton Drive、pCloud、ownCloud、</strong> 和 <strong>Nextcloud</strong>。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-options.png" alt=""></p><p>你可以自定義該工具的服務器名稱，然後點擊“<ruby>登錄<rt>Log in</rt></ruby>”開始授權過程。pCloud 的情況如下：</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-pcloud.png" alt=""></p><p>當你授權應用訪問雲文件，它會提示你設置本地文件夾和雲之間的同步。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-sync-location.png" alt=""></p><p>如果還沒有正斜槓（<code>/</code>） 符號，那麼只需輸入它即可，它應該開始以下拉樣式列出你擁有的遠程文件夾。</p><blockquote><p>💡 這將是雙向同步。因此，你的雲文件將被下載到遠程文件夾（如果有）。同步後，從雲中刪除的任何內容都不會從本地文件夾中消失。而且，你從系統中刪除的任何內容都將從雲中刪除。</p></blockquote><p><strong>此同步過程定期發生。</strong> 我沒有找到強制啓動或停止同步的方法。如果此應用的未來版本中提供類似的選項，它應該會有所幫助。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-gui-sync-check.png" alt=""></p><p>在大多數情況下，每當本地/遠程中發生文件更改時，同步都會確保你能夠儘快訪問最新的更改。</p><p>有一次，很長一段時間沒有同步，所以我不得不重新啓動應用來修復它。</p><p>不幸的是，如果雲提供商的令牌過期，該應用不能很好地處理錯誤，並且你必須重新授權和重新同步。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/celeste-dropbox-error.png" alt=""></p><p>它會顯示錯誤，但沒有使用 GUI 刷新令牌的選項。我不想嘗試命令列方式，因為這違背了 GUI 工具的目的。</p><p>因此，你可以選擇再次重新添加相同的同步服務器，重新進行所有授權和同步。這就是目前的解決方案。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Celeste 似乎是一個非常有用且簡單的 GUI 同步客户端。</p><p>儘管它缺乏某些功能，但用户體驗對於它已經提供的功能來説還是很好的。</p><p>考慮到它是一個相當新的應用，有更多的貢獻者和用户嘗試它，Celeste 可以憑藉其堅實的基礎發展成更多的東西。</p><p>你覺得 Celeste 怎麼樣？ 在下面的評論中分享你的想法。</p><p><em>（題圖：DA/48cf6b8e-8f5a-46e4-a7c1-50fe1cfd068f）</em></p><hr>',34)),n("p",null,[t[8]||(t[8]=e("via: ",-1)),l(s,{href:"https://news.itsfoss.com/celeste/"},{default:o(()=>[...t[7]||(t[7]=[e("https://news.itsfoss.com/celeste/",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("作者：",-1)),l(s,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...t[9]||(t[9]=[e("Ankush Das",-1)])]),_:1}),t[14]||(t[14]=e(" 選題：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[10]||(t[10]=[e("lujun9972",-1)])]),_:1}),t[15]||(t[15]=e(" 譯者：",-1)),l(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[11]||(t[11]=[e("geekpi",-1)])]),_:1}),t[16]||(t[16]=e(" 校對：",-1)),l(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=e("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[e("LCTT",-1)])]),_:1}),t[20]||(t[20]=e(" 原創編譯，",-1)),l(s,{href:"https://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[e("Linux中國",-1)])]),_:1}),t[21]||(t[21]=e(" 榮譽推出",-1))])])}const w=p(m,[["render",d]]);export{k as __pageData,w as default};
